INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4fe0aac2-3e43-4dc9-9ea8-68e39b3ac91b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$131. óra: Az oszthatóságról tanultak összefoglalása$q$, $q$Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "dc13b5d9-34dd-4d6d-9437-648ab7b234b8", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "e83584b1-3af6-45d3-b1e9-5c9572e5f60d", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "f6cb03b4-23d5-41b6-a45c-5936f46dc9eb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f2b73ce8-73c5-49e5-b3b5-f0ae3e8c6458", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "b2ad56fa-be26-4eb6-b1e1-5b5a9ea405ea", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "a4da280f-b0ad-4df1-b303-5e1a131b4cfa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9f68cb6-944a-45b0-b933-420ddee4f624", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "66a64395-1572-4fbd-8eb4-9dc4415f2b14", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "a5359772-50ea-4be4-acc4-1ccd1b43354a", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "2190ff02-c60f-4837-b1b1-4e9ef8aa9038", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "ed78c902-8bc4-457b-b33a-4a9fcdc1da47", "text": "Igaz", "isCorrect": true}, {"id": "ccb2cddd-5104-479d-91e1-694b04184639", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "77fdffac-aead-4321-bc12-f7ded7589dcb", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "1bb5b2f8-ae80-4852-ba01-33a93b0ac1d0", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "e4cda71a-840c-4699-801b-e9c7927a3b21", "text": "815", "isCorrect": false}, {"id": "b8a6ee78-a468-494a-b40f-521af80e1c19", "text": "812", "isCorrect": false}, {"id": "2a4555bd-3e4c-4a52-811a-784372077829", "text": "811", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('da2c4883-9bce-4e2c-8734-9d623aa3582e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$132. óra: A törtekről tanultak összefoglalása, vegyes feladatok$q$, $q$Év végi ismétlés: közönséges és tizedes törtek műveletei.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "1ccc5853-0e3f-48b6-bb2f-ea92bbaa4105", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "510d1d21-077e-41c4-b79e-d74548c0fab4", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "01bd65fc-a112-4ebc-9e9d-109aea29adec", "text": "4/6", "isCorrect": false}, {"id": "e4f96989-4fc3-4e03-b0be-6c83ee5b9bff", "text": "4/4", "isCorrect": false}, {"id": "03ffb69b-be81-46d9-8e9f-3870f224526e", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "49bceed1-5791-4d6e-84d1-11048444898c", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "51d11cc3-12eb-4343-a847-8797d90403c5", "text": "2/5", "isCorrect": true}, {"id": "ea01bd3b-e971-46d4-ba2e-cf7939bed7b9", "text": "6/15", "isCorrect": false}, {"id": "9363dcb4-3ef6-4507-b2d0-95fd24d09cae", "text": "5/8", "isCorrect": false}, {"id": "4af4b1a8-86f5-446d-8a09-a5fc37516207", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "90c0c9d2-0eae-49be-a9b4-b17cb3a6f971", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "2db14a62-2607-46bd-b5e6-efe569a68e4d", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "60bf714b-dfbc-4590-800f-7cb25583740d", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "a29cea49-6791-4806-9ac3-1a929791ea54", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "0368e988-48f0-42ca-bf59-2fa0b33ee74d", "text": "Igaz", "isCorrect": true}, {"id": "cfff1e11-ad91-4837-8b38-1900fbe2c864", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c848eae-4bd1-4344-b7a8-41a1c5bdacb1", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e4712dcb-9262-4d93-852f-a047024c8247', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$133. óra: A geometriai ismeretek összefoglalása, vegyes feladatok$q$, $q$Év végi ismétlés: szögek, alakzatok, tengelyes tükrözés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "5c0471fa-0f08-4efd-8acb-090d42cf6716", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "453cde14-504f-47d5-a31c-4c3368c7070a", "text": "Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "05c2aea7-ad4e-4a7d-acb3-e06c908705f9", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "aaf2a53b-e0f3-4ed6-8ed0-2bfb19d62af3", "text": "Ha a kör sugara 6 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "e7f78068-539c-4e7b-82cd-a961e1ca203f", "text": "A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "f71d5675-e51d-401e-a924-e2943c64da0e", "text": "Igaz", "isCorrect": true}, {"id": "6dbd7342-079e-43dc-9257-fc5550bd01bc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7b488a73-f369-4625-bce8-d1f7b87135fc", "text": "Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "3cd77f9d-2a9f-4014-a30d-a1536930b98c", "text": "Milyen szög a 90°-os szög?", "type": "multiple-choice", "options": [{"id": "414197c1-a463-453b-8335-25cdae866ff1", "text": "Derékszög", "isCorrect": true}, {"id": "9ed90ba4-e4ae-4e91-a24c-5a4b7315bf02", "text": "Hegyesszög", "isCorrect": false}, {"id": "a63cb7f6-49ce-4f8b-9d50-50a83ff76405", "text": "Tompaszög", "isCorrect": false}, {"id": "9136a328-cde9-4afc-83e6-fb94290edab5", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b4e51c94-5a61-4897-8592-021e5da792d3', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$134. óra: Arányosság, százalék, szöveges feladatok$q$, $q$Év végi ismétlés: egyenes arányosság, százalékszámítás, nyitott mondatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "5b19a9a0-c87e-45dc-a38b-716dbdcfaff6", "text": "Ossz el 500 Ft-ot 2 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "1c527cdd-a2fc-4f51-b0f0-3e00376b7415", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 7 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2800"}, {"id": "16dd1a39-4c50-424a-86a6-9447c2f10578", "text": "Mennyi 4000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "800"}, {"id": "ec6ee304-0c39-4fa6-b8e3-dd7dd6d5e179", "text": "Melyik szám teszi igazzá: 3 * x + 5 = 26? (21/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "4be48efb-0b2b-4350-85ed-babb71fe17cc", "text": "Gondoltam egy számot, elosztottam 4-gyel, hozzáadtam 6-ot, 11-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "190d6996-af77-4a19-81cd-8b12d9b91537", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "debcf60f-a91e-451b-a4a5-3c0eefd1ce75", "text": "Igaz", "isCorrect": true}, {"id": "b14a7c01-d9e6-433a-b491-f87abaaf2465", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d6503ba5-baae-4fb7-9135-400c5768caed", "text": "Hány százalék felel meg a 4/5 törtszám teljes értékének?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('41e29fc6-4018-4359-a355-5ad2ca458292', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$135. óra: A hosszúság, a kerület, a terület és a térfogat fogalmával kapcsolatos feladatok$q$, $q$Év végi ismétlés: mérések, kerület, terület, felszín, térfogat.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "72cdff84-89b7-49bb-8d3e-054c52936050", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "2379207b-b524-43bd-ab11-ada83ba3137d", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "41d23bfd-f42b-47ff-9b78-09db1e32fa0e", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "e22d7daf-d3ff-47f7-a082-39982999d0ff", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "b1d1ad38-0bbb-4f64-bc6e-d551ef47c885", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "6cc090b1-90c9-44dd-be06-02c94445b80d", "text": "Igaz", "isCorrect": true}, {"id": "b934da9c-6ee2-467e-8435-4d2db5df4a2b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "098560eb-a3de-406b-b75e-9d44bce81f7c", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "1424d84d-1f0d-4690-a546-208e71e339c7", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('172e246f-e150-4a2a-b2ed-ff1848992451', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$136. óra: Az éves munka értékelése$q$, $q$Az 6. osztályos matematika törzsanyag sikeres teljesítésének záró értékelése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "92d649af-0fcc-45b7-9479-dec400b749e0", "text": "Mely főbb témaköröket dolgoztuk fel a 6. osztályos matematika tananyagban?", "type": "multiple-choice", "options": [{"id": "ff61c837-9b25-4a65-92e2-17cb7651ee4e", "text": "Egész számok, oszthatóság, törtek, geometria, arány és százalék, kerület-terület-felszín-térfogat, statisztika, pénzügyek", "isCorrect": true}, {"id": "feac74fb-3b24-4910-8cdf-91a777d705ba", "text": "Kizárólag geometria", "isCorrect": false}, {"id": "96a390cb-b53a-45db-8368-1a3fb3470e87", "text": "Kizárólag rajzolás", "isCorrect": false}, {"id": "1e93e5fb-6f90-480d-841b-66927b6038c9", "text": "Csak az 1. osztályos ismétlés", "isCorrect": false}], "timeLimit": 15}, {"id": "de0d87ff-944c-4be7-8243-56bdfe97ec2d", "text": "A szorgalmas felkészülés és a rendszerezett gyakorlás a matematikai tudás alapja.", "type": "true-false", "options": [{"id": "c4fcc65e-689c-4034-8177-7572b4c43bb2", "text": "Igaz", "isCorrect": true}, {"id": "e220ea00-f555-4232-9a1b-33e2c2147824", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0684b62e-9028-426c-be1d-31599fb75d7a", "text": "Hány órából állt a 6. osztályos teljes matematika tananyag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "136"}, {"id": "46a28866-701f-4a90-92ab-731acce4894d", "text": "A megszerzett matematikai tudás segít a mindennapi pénzügyekben és a döntéshozatalban.", "type": "true-false", "options": [{"id": "4b0ca2d4-e155-4ab5-8fe6-7b8a67a07355", "text": "Igaz", "isCorrect": true}, {"id": "7c74d829-842f-4501-ab10-90a2e810e275", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a2892ddb-7e67-49ae-9bfb-13316df054e8", "text": "Gratulálunk a 6. osztályos matematika tananyag sikeres teljesítéséhez!", "type": "true-false", "options": [{"id": "6aeb9dfb-78a3-4fee-82b4-6bf467e9d122", "text": "Igaz", "isCorrect": true}, {"id": "6d6778e3-0224-4459-993f-13c14c225603", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9f48788d-1f3e-4215-89af-56991b031c2d", "text": "A 7. osztályban az itt megszerzett alapokra (pl. oszthatóság, törtek, százalék, geometria) építünk tovább.", "type": "true-false", "options": [{"id": "2a84247a-f64d-4c6e-aba6-2b19ff4d44cc", "text": "Igaz", "isCorrect": true}, {"id": "6e3b0913-d014-4c02-8cfb-cbbac2179d4b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a8d1734c-9e4a-44c7-9f58-b9c93b4ee17e", "text": "Melyik volt a kedvenc témaköröd ebben a tanévben?", "type": "multiple-choice", "options": [{"id": "6d5ca8c8-0ecc-432f-a3a1-64a55ad750ef", "text": "Mindegyik témakör hasznos és érdekes volt!", "isCorrect": true}, {"id": "911149bc-99d7-44a7-9c5c-43d4a9feb592", "text": "Egész számok és oszthatóság", "isCorrect": false}, {"id": "3c17228e-72f9-4319-a09d-3d3f2cfed92f", "text": "Geometria és tengelyes tükrözés", "isCorrect": false}, {"id": "0446556a-9a24-4ace-89fa-274d935a26a1", "text": "Arányosság és százalékszámítás", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;